// Состояние — массив задач
let todos = [
  { id: 1, text: "Научиться JS", done: true },
  { id: 2, text: "Собрать калькулятор", done: false },
  { id: 3, text: "Собрать To-Do List", done: false }
];

// Ключевые операции:
// 1. Добавить задачу: todos.push()
// 2. Удалить задачу: todos.filter()
// 3. Переключить статус: todos.map()
// 4. Отрисовать: функция, которая строит HTML из todos

// Create — добавить задачу
function addTodo(text) {
  todos.push({
    id: Date.now(),  // уникальный ID
    text: text,
    done: false
  });
}

// Read — получить все задачи
function getAllTodos() {
  return todos;
}

// Update — переключить статус
function toggleTodo(id) {
  todos = todos.map(todo =>
    todo.id === id ? { ...todo, done: !todo.done } : todo
  );
}

// Delete — удалить по ID
function deleteTodo(id) {
  todos = todos.filter(todo => todo.id !== id);
}

function renderTodos() {
  const container = document.querySelector("#todo-list");
  container.innerHTML = "";  // очищаем старую отрисовку

  for (const todo of todos) {
    // Создаём элемент
    const li = document.createElement("li");
    li.className = todo.done ? "done" : "";

    // Текст задачи
    const span = document.createElement("span");
    span.textContent = todo.text;
    li.appendChild(span);

    // Кнопка удаления
    const btn = document.createElement("button");
    btn.textContent = "X";
    btn.addEventListener("click", () => deleteTodo(todo.id));
    li.appendChild(btn);

    container.appendChild(li);
  }
}

