// БАГ: изменили данные, но не перерисовали!
function addTodo(text) {
  todos.push({ id: Date.now(), text, done: false });
  // забыли renderTodos()!
}

// ПРАВИЛЬНО: после каждого изменения — перерисовка
function addTodo(text) {
  todos.push({ id: Date.now(), text, done: false });
  renderTodos();  // обновляем интерфейс
}

// ПЛОХО: мутация существующего массива
function clearAll() {
  todos.length = 0;  // мутируем!
  renderTodos();
}

// ХОРОШО: создаём новый массив
function clearAll() {
  todos = [];  // новый массив
  renderTodos();
}

// ИЛИ: через filter
function deleteDone() {
  todos = todos.filter(t => !t.done);  // новый массив
  renderTodos();
}

function renderTodos(filter) {
  const container = document.querySelector("#todo-list");
  container.innerHTML = "";

  let list = todos;
  if (filter === "active") {
    list = todos.filter(t => !t.done);
  } else if (filter === "done") {
    list = todos.filter(t => t.done);
  }

  for (const todo of list) {
    const li = document.createElement("li");
    li.className = todo.done ? "done" : "";
    li.textContent = todo.text;
    container.appendChild(li);
  }
}

// Обработчик: добавление задачи
const form = document.querySelector("#todo-form");
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const input = document.querySelector("#todo-input");
  const text = input.value.trim();
  if (text) {
    addTodo(text);
    input.value = "";  // очищаем поле
  }
});

// Обработчик: удаление задачи
list.addEventListener("click", (event) => {
  const btn = event.target.closest("button");
  if (btn) {
    const id = Number(btn.dataset.id);
    deleteTodo(id);
  }
});

function updateCounter() {
  const total = todos.length;
  const done = todos.filter(t => t.done).length;
  const active = total - done;

  document.querySelector("#total").textContent = `Всего: ${total}`;
  document.querySelector("#done").textContent = `Выполнено: ${done}`;
  document.querySelector("#active").textContent = `Активных: ${active}`;
}

// Вызываем после каждой операции:
function addTodo(text) {
  todos.push({ id: Date.now(), text, done: false });
  renderTodos();
  updateCounter();
}

