// spread { ...t, done: !t.done } — создаёт НОВЫЙ объект
// Старый объект остаётся неизменным — это иммутабельное обновление

// Загрузка при старте
function loadTodos() {
  const saved = localStorage.getItem("todos");
  if (saved) {
    todos = JSON.parse(saved);
  }
}

// Сохранение после каждого изменения
function saveTodos() {
  localStorage.setItem("todos", JSON.stringify(todos));
}

// Вызываем после каждой операции:
function addTodo(text) {
  todos.push({ id: Date.now(), text, done: false });
  renderTodos();
  saveTodos();  // сохраняем!
}

